session_name('p2p_session');
session_set_cookie_params(['httponly'=>true,'secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'samesite'=>'Lax','path'=>'/']);
ini_set('session.use_strict_mode','1'); session_start();
const APP_NAME='P2P Calculator';
$dbPath=__DIR__.'/p2p-calculator.sqlite';
try {$db=new PDO('sqlite:'.$dbPath,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); $db->exec('PRAGMA foreign_keys=ON'); $db->exec('PRAGMA journal_mode=WAL');
$db->exec("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,nickname TEXT NOT NULL COLLATE NOCASE UNIQUE,telegram TEXT NOT NULL,passhash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'student',status TEXT NOT NULL DEFAULT 'active',language TEXT NOT NULL DEFAULT 'ru',theme TEXT NOT NULL DEFAULT 'dark',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen TEXT)");
$db->exec("CREATE TABLE IF NOT EXISTS banks(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT NOT NULL,limit_amount NUMERIC NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE)");
$db->exec("CREATE TABLE IF NOT EXISTS trades(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,buy_exchange TEXT NOT NULL,buy_bank_id INTEGER,buy_rate NUMERIC NOT NULL,buy_amount NUMERIC NOT NULL,buy_fee NUMERIC NOT NULL DEFAULT 0,buy_fee_type TEXT NOT NULL DEFAULT 'fixed',sell_exchange TEXT NOT NULL,sell_bank_id INTEGER,sell_rate NUMERIC NOT NULL,sell_amount NUMERIC NOT NULL,sell_fee NUMERIC NOT NULL DEFAULT 0,sell_fee_type TEXT NOT NULL DEFAULT 'fixed',extra_cost NUMERIC NOT NULL DEFAULT 0,comment TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(buy_bank_id) REFERENCES banks(id) ON DELETE SET NULL,FOREIGN KEY(sell_bank_id) REFERENCES banks(id) ON DELETE SET NULL)");
$db->exec("CREATE TABLE IF NOT EXISTS settings(k TEXT PRIMARY KEY,v TEXT NOT NULL)"); $db->exec("CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,admin_id INTEGER,action TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)");
} catch(Throwable $e){http_response_code(500);exit('Ошибка инициализации базы данных. Проверьте права на запись в папку сайта и наличие PDO_SQLite.');}
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function go(string $url='?'):never{header('Location: '.$url);exit;}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function checkCsrf():void{if(!hash_equals($_SESSION['csrf']??'',(string)($_POST['csrf']??''))){http_response_code(403);exit('Недействительный запрос. Обновите страницу и попробуйте снова.');}}
function me(PDO $db):?array{if(empty($_SESSION['uid']))return null;$s=$db->prepare('SELECT id,nickname,telegram,role,status,language,theme,created_at FROM users WHERE id=?');$s->execute([$_SESSION['uid']]);$u=$s->fetch();if(!$u||$u['status']!=='active'){unset($_SESSION['uid']);return null;}return $u;}
function needUser(?array $u):void{if(!$u)go('?page=login');}
function adminOnly(?array $u):void{needUser($u);if($u['role']!=='admin'){http_response_code(403);exit('Доступ запрещён.');}}
function setting(PDO $db,string $k,string $default=''):string{$s=$db->prepare('SELECT v FROM settings WHERE k=?');$s->execute([$k]);$v=$s->fetchColumn();return $v===false?$default:(string)$v;}
function saveSetting(PDO $db,string $k,string $v):void{$s=$db->prepare('INSERT INTO settings(k,v) VALUES(?,?) ON CONFLICT(k) DO UPDATE SET v=excluded.v');$s->execute([$k,$v]);}
function fee(float $amount,float $v,string $type):float{return $type==='percent'?$amount*$v/100:$v;}
function calc(array $t):array{$buy=(float)$t['buy_amount'];$br=(float)$t['buy_rate'];$sr=(float)$t['sell_rate'];$sold=(float)$t['sell_amount'];$bf=fee($buy,(float)$t['buy_fee'],$t['buy_fee_type']);$sf=fee($sold,(float)$t['sell_fee'],$t['sell_fee_type']);$usdt=$br>0?max(0,$buy-$bf)/$br:0;$revenue=$sold>0?$sold:$usdt*$sr;$cost=$buy+$bf+(float)$t['extra_cost'];$profit=$revenue-$cost-$sf;return ['usdt'=>$usdt,'revenue'=>$revenue,'cost'=>$cost,'profit'=>$profit,'roi'=>$cost>0?$profit/$cost*100:0,'spread'=>$sr-$br,'buyfee'=>$bf,'sellfee'=>$sf];}
function money(float $n):string{return number_format($n,2,'.',' ');}
$u=me($db);$page=(string)($_GET['page']??'dashboard');$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 checkCsrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='register'){
