   if(!preg_match('/^[\p{L}\p{N}_-]{3,32}$/u',$nick))throw new RuntimeException('Никнейм: 3–32 символа, буквы, цифры, _ или -.');
   if(!preg_match('/^@?[A-Za-z0-9_]{5,32}$/',$tg))throw new RuntimeException('Проверьте Telegram-ник.');if(strlen($pw)<10||!preg_match('/[A-Za-z]/',$pw)||!preg_match('/\d/',$pw))throw new RuntimeException('Пароль должен содержать минимум 10 символов, буквы и цифры.');if($pw!==$pw2)throw new RuntimeException('Пароли не совпадают.');
   $s=$db->prepare('INSERT INTO users(nickname,telegram,passhash) VALUES(?,?,?)');$s->execute([$nick,'@'.ltrim($tg,'@'),password_hash($pw,PASSWORD_DEFAULT)]);$success='Аккаунт создан. Теперь войдите.';$page='login';
  }elseif($action==='login'){
   $ip=(string)($_SERVER['REMOTE_ADDR']??'');$key='login_'.hash('sha256',$ip);$_SESSION[$key]??=['n'=>0,'at'=>time()];if(time()-$_SESSION[$key]['at']>900)$_SESSION[$key]=['n'=>0,'at'=>time()];if($_SESSION[$key]['n']>=8)throw new RuntimeException('Слишком много попыток. Подождите 15 минут.');
   $s=$db->prepare('SELECT * FROM users WHERE nickname=? COLLATE NOCASE');$s->execute([trim((string)($_POST['nickname']??''))]);$row=$s->fetch();if(!$row||!password_verify((string)($_POST['password']??''),$row['passhash'])||$row['status']!=='active'){$_SESSION[$key]['n']++;throw new RuntimeException('Неверный никнейм или пароль.');}session_regenerate_id(true);$_SESSION['uid']=(int)$row['id'];unset($_SESSION[$key]);$db->prepare('UPDATE users SET last_seen=CURRENT_TIMESTAMP WHERE id=?')->execute([$row['id']]);go('?');
  }elseif($action==='logout'){$_SESSION=[];if(ini_get('session.use_cookies')){ $p=session_get_cookie_params();setcookie(session_name(),'',['expires'=>time()-42000,'path'=>$p['path'],'secure'=>$p['secure'],'httponly'=>$p['httponly'],'samesite'=>$p['samesite']]);}session_destroy();go('?page=login');
  }elseif($action==='save_trade'){needUser($u);$id=(int)($_POST['id']??0);$num=['buy_rate','buy_amount','buy_fee','sell_rate','sell_amount','sell_fee','extra_cost'];$v=[];foreach($num as $k){$raw=str_replace(',','.',(string)($_POST[$k]??'0'));if(!is_numeric($raw)||!is_finite((float)$raw)||(float)$raw<0)throw new RuntimeException('Проверьте числовые значения.');$v[$k]=(float)$raw;}if($v['buy_rate']<=0||$v['sell_rate']<=0||$v['buy_amount']<=0)throw new RuntimeException('Курсы и сумма покупки должны быть больше нуля.');
   $bb=(int)($_POST['buy_bank_id']??0)?:null;$sb=(int)($_POST['sell_bank_id']??0)?:null;foreach([$bb,$sb] as $bid){if($bid){$q=$db->prepare('SELECT id FROM banks WHERE id=? AND user_id=? AND archived=0');$q->execute([$bid,$u['id']]);if(!$q->fetch())throw new RuntimeException('Выбранный банк недоступен.');}}
   $data=[$u['id'],trim((string)($_POST['buy_exchange']??'Binance')),$bb,$v['buy_rate'],$v['buy_amount'],$v['buy_fee'],($_POST['buy_fee_type']??'fixed')==='percent'?'percent':'fixed',trim((string)($_POST['sell_exchange']??'Binance')),$sb,$v['sell_rate'],$v['sell_amount'],$v['sell_fee'],($_POST['sell_fee_type']??'fixed')==='percent'?'percent':'fixed',$v['extra_cost'],mb_substr(trim((string)($_POST['comment']??'')),0,500)];
   if($id){$q=$db->prepare('UPDATE trades SET buy_exchange=?,buy_bank_id=?,buy_rate=?,buy_amount=?,buy_fee=?,buy_fee_type=?,sell_exchange=?,sell_bank_id=?,sell_rate=?,sell_amount=?,sell_fee=?,sell_fee_type=?,extra_cost=?,comment=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND user_id=?');$q->execute(array_merge(array_slice($data,1),[$id,$u['id']]));}else{$q=$db->prepare('INSERT INTO trades(user_id,buy_exchange,buy_bank_id,buy_rate,buy_amount,buy_fee,buy_fee_type,sell_exchange,sell_bank_id,sell_rate,sell_amount,sell_fee,sell_fee_type,extra_cost,comment) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute($data);}go('?page=history');
  }elseif($action==='delete_trade'){needUser($u);$db->prepare('DELETE FROM trades WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],$u['id']]);go('?page=history');
  }elseif($action==='save_bank'){needUser($u);$name=trim((string)($_POST['name']??''));$lim=str_replace(',','.',(string)($_POST['limit_amount']??'0'));if($name===''||mb_strlen($name)>80||!is_numeric($lim)||(float)$lim<0)throw new RuntimeException('Укажите корректное название и лимит.');$id=(int)($_POST['id']??0);if($id)$db->prepare('UPDATE banks SET name=?,limit_amount=? WHERE id=? AND user_id=?')->execute([$name,(float)$lim,$id,$u['id']]);else$db->prepare('INSERT INTO banks(user_id,name,limit_amount) VALUES(?,?,?)')->execute([$u['id'],$name,(float)$lim]);go('?page=banks');
  }elseif($action==='archive_bank'){needUser($u);$db->prepare('UPDATE banks SET archived=1 WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],$u['id']]);go('?page=banks');
  }elseif($action==='settings'){needUser($u);$tg=trim((string)($_POST['telegram']??''));$lang=(string)($_POST['language']??'ru');$theme=(string)($_POST['theme']??'dark');if(!in_array($lang,['ru','uk','en'],true)||!in_array($theme,['dark','light'],true)||!preg_match('/^@?[A-Za-z0-9_]{5,32}$/',$tg))throw new RuntimeException('Проверьте настройки профиля.');$db->prepare('UPDATE users SET telegram=?,language=?,theme=? WHERE id=?')->execute(['@'.ltrim($tg,'@'),$lang,$theme,$u['id']]);go('?page=settings');
  }elseif($action==='change_password'){needUser($u);$q=$db->prepare('SELECT passhash FROM users WHERE id=?');$q->execute([$u['id']]);if(!password_verify((string)($_POST['old_password']??''),(string)$q->fetchColumn()))throw new RuntimeException('Текущий пароль указан неверно.');$pw=(string)($_POST['new_password']??'');if(strlen($pw)<10||!preg_match('/[A-Za-z]/',$pw)||!preg_match('/\d/',$pw))throw new RuntimeException('Новый пароль должен содержать минимум 10 символов, буквы и цифры.');$db->prepare('UPDATE users SET passhash=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$u['id']]);session_regenerate_id(true);$success='Пароль изменён.';
  }elseif($action==='admin_bootstrap'){
   $key=(string)($_POST['admin_key']??'');$env=(string)(getenv('APP_ADMIN_KEY')?:'');if($env===''||!hash_equals($env,$key))throw new RuntimeException('Неверный ключ. APP_ADMIN_KEY должен быть настроен на сервере.');$count=(int)$db->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn();if($count>0)throw new RuntimeException('Администратор уже создан.');$nick=trim((string)$_POST['nickname']);$tg=trim((string)$_POST['telegram']);$pw=(string)$_POST['password'];if(!preg_match('/^[\p{L}\p{N}_-]{3,32}$/u',$nick)||!preg_match('/^@?[A-Za-z0-9_]{5,32}$/',$tg)||strlen($pw)<12)throw new RuntimeException('Проверьте данные: пароль администратора — минимум 12 символов.');$db->prepare("INSERT INTO users(nickname,telegram,passhash,role) VALUES(?,?,?,'admin')")->execute([$nick,'@'.ltrim($tg,'@'),password_hash($pw,PASSWORD_DEFAULT)]);$db->prepare('INSERT INTO audit(admin_id,action,details) VALUES(?,?,?)')->execute([(int)$db->lastInsertId(),'bootstrap','Первый администратор создан']);$success='Администратор создан. Войдите в аккаунт.';$page='login';
  }elseif($action==='admin_user'){adminOnly($u);$id=(int)$_POST['id'];$status=(string)$_POST['status'];if(!in_array($status,['active','blocked'],true))throw new RuntimeException('Недопустимый статус.');if($id===$u['id'])throw new RuntimeException('Нельзя заблокировать собственный аккаунт.');$db->prepare('UPDATE users SET status=? WHERE id=?')->execute([$status,$id]);$db->prepare('INSERT INTO audit(admin_id,action,details) VALUES(?,?,?)')->execute([$u['id'],'user_status','user_id='.$id.' status='.$status]);go('?page=admin');
  }elseif($action==='admin_setting'){adminOnly($u);$k=(string)$_POST['key'];if(!in_array($k,['site_name','support_telegram'],true))throw new RuntimeException('Настройка недоступна.');$val=trim((string)$_POST['value']);if($k==='support_telegram'&&!preg_match('/^@?[A-Za-z0-9_]{5,32}$/',$val))throw new RuntimeException('Некорректный Telegram.');if($k==='site_name'&&($val===''||mb_strlen($val)>80))throw new RuntimeException('Название должно содержать 1–80 символов.');saveSetting($db,$k,$val);$db->prepare('INSERT INTO audit(admin_id,action,details) VALUES(?,?,?)')->execute([$u['id'],'setting',$k]);go('?page=admin');
  }
 }catch(PDOException $ex){$error=str_contains(strtolower($ex->getMessage()),'unique')?'Такой никнейм уже занят.':'Не удалось сохранить данные. Проверьте ввод и попробуйте снова.';}catch(Throwable $ex){$error=$ex->getMessage();}
}
