<div class="card"><h2><?= $edit?'Редактировать сделку':'Новый расчёт'?></h2><form method="post" id="tradeform"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_trade"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="formgrid"><div class="field"><label>Биржа покупки</label><input name="buy_exchange" value="<?=e($vals['buy_exchange'])?>" required></div><div class="field"><label>Банк покупки</label><select name="buy_bank_id"><option value="">Не выбран</option><?php foreach($banks as $b):?><option value="<?=$b['id']?>" <?=((string)$vals['buy_bank_id']===(string)$b['id'])?'selected':''?>><?=e($b['name'])?></option><?php endforeach?></select></div><div class="field"><label>Курс покупки (грн/USDT)</label><input type="number" step="any" min="0.000001" name="buy_rate" id="br" value="<?=e($vals['buy_rate'])?>" required></div><div class="field"><label>Сумма покупки (грн)</label><input type="number" step="any" min="0.01" name="buy_amount" id="ba" value="<?=e($vals['buy_amount'])?>" required></div><div class="field"><label>Комиссия покупки</label><input type="number" step="any" min="0" name="buy_fee" id="bf" value="<?=e($vals['buy_fee'])?>"></div><div class="field"><label>Тип комиссии покупки</label><select name="buy_fee_type" id="bft"><option value="fixed" <?=$vals['buy_fee_type']==='fixed'?'selected':''?>>Фиксированная сумма, грн</option><option value="percent" <?=$vals['buy_fee_type']==='percent'?'selected':''?>>Процент от суммы</option></select></div><div class="field"><label>Биржа продажи</label><input name="sell_exchange" value="<?=e($vals['sell_exchange'])?>" required></div><div class="field"><label>Банк продажи</label><select name="sell_bank_id"><option value="">Не выбран</option><?php foreach($banks as $b):?><option value="<?=$b['id']?>" <?=((string)$vals['sell_bank_id']===(string)$b['id'])?'selected':''?>><?=e($b['name'])?></option><?php endforeach?></select></div><div class="field"><label>Курс продажи (грн/USDT)</label><input type="number" step="any" min="0.000001" name="sell_rate" id="sr" value="<?=e($vals['sell_rate'])?>" required></div><div class="field"><label>Сумма продажи (грн, 0 = рассчитать автоматически)</label><input type="number" step="any" min="0" name="sell_amount" id="sa" value="<?=e($vals['sell_amount'])?>"></div><div class="field"><label>Комиссия продажи</label><input type="number" step="any" min="0" name="sell_fee" id="sf" value="<?=e($vals['sell_fee'])?>"></div><div class="field"><label>Тип комиссии продажи</label><select name="sell_fee_type" id="sft"><option value="fixed" <?=$vals['sell_fee_type']==='fixed'?'selected':''?>>Фиксированная сумма, грн</option><option value="percent" <?=$vals['sell_fee_type']==='percent'?'selected':''?>>Процент от суммы</option></select></div><div class="field"><label>Дополнительные расходы (грн)</label><input type="number" step="any" min="0" name="extra_cost" id="ex" value="<?=e($vals['extra_cost'])?>"></div><div class="field"><label>Комментарий</label><input name="comment" maxlength="500" value="<?=e($vals['comment'])?>"></div></div><div class="grid"><div class="card"><div class="muted">Куплено USDT (расчётно)</div><div class="value" id="outusdt">—</div></div><div class="card"><div class="muted">Чистая прибыль, грн</div><div class="value" id="outprofit">—</div></div><div class="card"><div class="muted">Доходность</div><div class="value" id="outroi">—</div></div><div class="card"><div class="muted">Спред</div><div class="value" id="outspread">—</div></div></div><div class="actions"><button>Сохранить сделку</button><a class="btn secondary" href="?page=calculator">Очистить форму</a></div></form></div>
<script>(()=>{const ids=['br','ba','bf','bft','sr','sa','sf','sft','ex'];const $=id=>document.getElementById(id);function num(id){return Math.max(0,parseFloat($(id).value)||0)}function calc(){let br=num('br'),ba=num('ba'),bf=num('bf'),sr=num('sr'),sa=num('sa'),sf=num('sf'),ex=num('ex');let bfee=$('bft').value==='percent'?ba*bf/100:bf;let usdt=br>0?Math.max(0,ba-bfee)/br:0;let revenue=sa>0?sa:usdt*sr;let sfee=$('sft').value==='percent'?revenue*sf/100:sf;let cost=ba+bfee+ex;let profit=revenue-cost-sfee;let fmt=x=>x.toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:6});$('outusdt').textContent=fmt(usdt);$('outprofit').textContent=fmt(profit)+' ₴';$('outprofit').className='value '+(profit>=0?'positive':'negative');$('outroi').textContent=(cost>0?fmt(profit/cost*100):'0')+'%';$('outspread').textContent=fmt(sr-br)+' ₴';}ids.forEach(id=>$(id).addEventListener('input',calc));calc()})();</script>
